/**
 * External Integrations Registry & Menu Catalog (lib/integrations/external/registry.ts).
 *
 * Defines the metadata catalog displayed in the DeskcommCRM External
 * Integrations Menu (Tenant Settings > External Integrations Hub).
 */

import type { ExternalIntegrationMetadata, ExternalProviderType } from "./types";
export type { ExternalIntegrationMetadata, ExternalProviderType } from "./types";

export const EXTERNAL_INTEGRATIONS_CATALOG: ReadonlyArray<ExternalIntegrationMetadata> = [
  {
    provider: "egosms",
    label: "EgoSMS (Uganda & East Africa SMS Gateway)",
    description:
      "Reliable SMS messaging gateway for East Africa. Sends OTPs, loan approval notices, payment reminders, and arrears alerts across Uganda, Kenya, and Tanzania.",
    documentation_url: "https://www.egosms.co/api/",
    required_fields: ["username", "password", "sender_id"],
    capabilities: ["sms_notification", "otp_delivery", "arrears_reminder"],
  },
  {
    provider: "documenso",
    label: "Documenso (Open-Source Digital Signatures)",
    description:
      "Self-hosted electronic signature platform. Digitally signs PDF Loan Agreements and Promissory Notes generated by @react-pdf/renderer.",
    documentation_url: "https://documenso.com/docs",
    required_fields: ["api_key", "api_url"],
    capabilities: ["digital_signature", "agreement_execution", "webhook_sync"],
  },
  {
    provider: "heyforms",
    label: "HeyForms (Onboarding & KYC Forms)",
    description:
      "Open-source online form builder. Captures loan application forms, guarantor questionnaires, and KYC disclosures, creating CRM leads automatically.",
    documentation_url: "https://heyform.net/docs",
    required_fields: ["api_key", "api_url", "webhook_secret"],
    capabilities: ["custom_forms", "lead_capture", "guarantor_questionnaire"],
  },
  {
    provider: "idswyft",
    label: "IdSwyft (KYC Identity Verification Platform)",
    description:
      "Open-source identity verification platform (Weareupsyd/idswyft-community-W). Validates national identity cards, passports, selfies, and credit compliance.",
    documentation_url: "https://github.com/Weareupsyd/idswyft-community-W",
    required_fields: ["api_key", "api_url"],
    capabilities: ["identity_verification", "document_ocr", "biometric_check"],
  },
  {
    provider: "minio",
    label: "MinIO (Self-Hosted S3 Object Storage)",
    description:
      "High-performance open-source object storage. Stores generated PDF agreements, KYC evidence files, and promissory notes with expiring signed URLs.",
    documentation_url: "https://min.io/docs/minio/linux/index.html",
    required_fields: ["endpoint", "access_key", "secret_key", "bucket_name"],
    capabilities: ["object_storage", "signed_urls", "pdf_repository"],
  },
];

export function getExternalIntegrationMetadata(
  provider: ExternalProviderType,
): ExternalIntegrationMetadata | undefined {
  return EXTERNAL_INTEGRATIONS_CATALOG.find((p) => p.provider === provider);
}
